using System;using System.IO;using UnityEngine;using SkyIsland;using SkyIsland.Authority;
public static class FoundationClientReview {
 sealed class Store:IAuthorityStore{public string json;public bool fail;public string Load()=>json;public void Commit(string data){if(fail)throw new IOException();json=data;}}
 public static void Validate(){AuthorityReview.Validate();int n=0;Action<bool,string> check=(v,name)=>{if(!v)throw new Exception("CLIENT FAIL "+name);n++;};
 var seed=new AuthorityState();seed.accounts.Add(new AccountState{id="a",wood=30,stone=20});seed.accounts.Add(new AccountState{id="b",wood=50,stone=40});seed.accounts.Add(new AccountState{id="c",wood=90,stone=90});seed.islands.Add(new IslandState{id="island",owner="a",builders=new System.Collections.Generic.List<string>{"b"},cells=new HexIsland().Snapshot(Vector3.zero).cells});var store=new Store();var world=new FoundationAuthority(store,seed,t=>t=="session-a"?"a":t=="session-b"?"b":t=="session-c"?"c":null);
 check(world.Snapshot("a","island").code=="UNAUTHENTICATED","snapshot needs server session");check(world.Snapshot("session-c","island").cells==null,"forbidden snapshot contains no geometry");var sa=world.Snapshot("session-a","island");var sb=world.Snapshot("session-b","island");check(sa.wood==30&&sb.wood==50,"snapshot only contains requesting account inventory");sa.cells[0]=new Hex(90,90);check(world.Snapshot("session-a","island").cells[0].q!=90,"snapshot detached from server");
 var a=new FoundationClient("island");var b=new FoundationClient("island");check(a.Begin(new Hex(2,0))==null,"cannot write before initial snapshot");check(a.AcceptSnapshot(world.Snapshot("session-a","island"))&&b.AcceptSnapshot(sb),"two independent replicas initialize");var request=a.Begin(new Hex(2,0));check(request!=null&&a.Waiting&&a.View.wood==30&&a.View.cells.Length==7,"no speculative debit or geometry");check(a.Begin(new Hex(3,0))==null,"one unresolved operation at a time");request.q=99;check(a.Retry().q==2,"caller cannot alter retry payload");var original=a.Retry();var result=world.Place("session-a",original);a.Disconnected();check(a.Waiting&&a.NeedsRefresh&&a.Retry().requestId==original.requestId,"disconnect retains ambiguous request identity");check(!a.Receive(new CommandResult{requestId=Guid.NewGuid().ToString("D"),code="OK"})&&a.Waiting,"unrelated response ignored");var restart=FoundationClient.Restore("island",a.Checkpoint());check(restart.Waiting&&restart.NeedsRefresh&&restart.Retry().requestId==original.requestId,"cold client restart retains unresolved identity and requires refresh");check(restart.Begin(new Hex(3,0))==null,"restored client cannot submit another intent");check(restart.Checkpoint().IndexOf("session-a",StringComparison.Ordinal)<0,"checkpoint never persists login session");bool rejected=false;try{FoundationClient.Restore("other",a.Checkpoint());}catch{rejected=true;}check(rejected,"wrong island checkpoint fails closed");var damaged=JsonUtility.FromJson<FoundationClientCheckpoint>(a.Checkpoint());damaged.pending.expectedRevision=-1;rejected=false;try{FoundationClient.Restore("island",JsonUtility.ToJson(damaged));}catch{rejected=true;}check(rejected,"corrupt pending command fails closed");
 var replay=world.Place("session-a",a.Retry());check(replay.code=="OK"&&world.Read("session-a","island").wood==27,"lost success replay no second debit");check(a.Receive(replay)&&a.NeedsRefresh&&!a.Waiting,"receipt requires fresh snapshot");check(a.Begin(new Hex(3,0))==null,"receipt alone cannot invent current geometry");check(a.AcceptSnapshot(world.Snapshot("session-a","island"))&&a.View.cells.Length==8,"committed geometry reconciles");
 var collision=b.Begin(new Hex(2,1));check(world.Place("session-b",collision).code=="VERSION_CONFLICT","other replica stale revision rejected");check(b.Receive(world.Place("session-b",b.Retry()))&&b.AcceptSnapshot(world.Snapshot("session-b","island")),"conflict refreshes without own debit");check(b.View.wood==50&&b.View.cells.Length==8,"shared geometry private account stock");check(!a.AcceptSnapshot(sb)&&a.View.revision==1,"late snapshot cannot roll back revision");var copy=a.View;copy.cells[0]=new Hex(99,99);check(a.View.cells[0].q!=99,"view getter cannot mutate replica");check(!a.AcceptSnapshot(new IslandView{code="OK",islandId="wrong",cells=sb.cells}),"wrong island snapshot rejected");check(!a.AcceptSnapshot(new IslandView{code="OK",islandId="island",revision=2,wood=1,stone=1,cells=new[]{new Hex(0,0),new Hex(5,5)}}),"disconnected geometry rejected");
 var goA=new GameObject("Authoritative scene A");var goB=new GameObject("Authoritative scene B");try{var va=goA.AddComponent<FoundationSceneView>();var vb=goB.AddComponent<FoundationSceneView>();check(va.Apply(a.View)&&vb.Apply(b.View)&&va.Count==8&&vb.Count==8,"two Unity scene projections reconcile actual meshes");check(!va.Apply(sb)&&va.Count==8,"scene rejects stale snapshot");check(va.Apply(a.View)&&va.Count==8&&goA.transform.childCount==8,"repeated snapshot does not duplicate objects");check(goA.transform.GetChild(0).GetComponent<MeshFilter>().sharedMesh.vertexCount==7,"actual hex mesh generated");var cmd=b.Begin(new Hex(2,1));check(b.Receive(world.Place("session-b",cmd))&&b.AcceptSnapshot(world.Snapshot("session-b","island")),"second player commits from refreshed revision");check(a.AcceptSnapshot(world.Snapshot("session-a","island"))&&va.Apply(a.View)&&vb.Apply(b.View)&&va.Count==9&&vb.Count==9,"both visible islands converge after other player write");check(a.View.wood==27&&b.View.wood==47,"both players debited only for their own construction");}finally{UnityEngine.Object.DestroyImmediate(goA);UnityEngine.Object.DestroyImmediate(goB);}
 var pending=a.Begin(new Hex(3,0));store.fail=true;var failed=world.Place("session-a",pending);check(!a.Receive(failed)&&a.Waiting,"storage uncertainty blocks new intent and preserves retry");check(world.Snapshot("session-a","island").code=="STORAGE_UNAVAILABLE","faulted server cannot publish stale success snapshot");
 Directory.CreateDirectory("../evidence/unity");File.WriteAllText("../evidence/unity/foundation-client-tests.txt","PASS "+n+" snapshot/client-retry/two-replica/Unity mesh projection checks. UTC "+DateTime.UtcNow.ToString("o")+"\nActual Unity objects and authority core, synchronous in-process session fixture. NOT live transport, main offline gameplay integration, production login, WebGL or two-player gameplay acceptance.\n");Debug.Log("SKY_FOUNDATION_CLIENT_PASS "+n);
 }
